def _norm(combos):
    return sorted(sorted(c) for c in combos)

def test_basic():
    assert _norm(sum_combinations([2, 3, 5], 8)) == [[2, 2, 2, 2], [2, 3, 3], [3, 5]]

def test_none_possible():
    assert sum_combinations([4, 6], 3) == []

def test_single_candidate():
    assert _norm(sum_combinations([3], 9)) == [[3, 3, 3]]

def test_no_duplicate_orderings():
    out = sum_combinations([2, 3, 6, 7], 7)
    assert _norm(out) == [[2, 2, 3], [7]]
    assert len(out) == 2

def test_count():
    out = sum_combinations([1, 2, 5], 10)
    assert len(out) == 10
    assert all(sum(c) == 10 for c in out)
